package mypackage;

public class Fibonacy {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		int x = 10;
		
		int f1 = 0;
		int f2 = 1;
		
		while(f1<x) {
			
			
			System.out.println(f1);
			
			int f3 = f1 + f2;
			
			f1=f2;
			f2=f3;
			
			
					
		}

	}

}
